window.CODE = Object.assign(window.CODE || {}, {"ch24/basic_crew.py":"\"\"\"A first crew: two agents, two tasks, run one after the other (Process.sequential).\n\n    scheduler  --(task 1: find the doctors)-->  writer  --(task 2: write the reply)-->  final answer\n\nRun:  python basic_crew.py\n\"\"\"\nfrom crewai import Agent, Crew, Process, Task\n\nfrom clinic_tools import get_doctor_schedule\nfrom crew_llm import get_llm\n\nllm = get_llm()\n\nscheduler = Agent(\n    role=\"Clinic scheduler\",\n    goal=\"Find which doctors are available, using only the schedule tool\",\n    backstory=\"You work at the City Clinic front desk. You never guess a doctor or a day; you look it up.\",\n    tools=[get_doctor_schedule],\n    llm=llm,\n    max_iter=4,                # at most 4 reasoning/tool rounds, then it must answer\n    allow_delegation=False,    # a specialist works alone; delegation is for managers (see hierarchical_crew.py)\n)\nwriter = Agent(\n    role=\"Patient reply writer\",\n    goal=\"Write a short, friendly reply that uses only the facts you were given\",\n    backstory=\"You write for patients. You never give medical advice and never add facts.\",\n    llm=llm,\n    allow_delegation=False,\n)\n\nfind_doctors = Task(\n    description=\"A patient asks: '{question}'. Find the doctors and the days that match.\",\n    expected_output=\"A short list of doctor names with their weekdays.\",\n    agent=scheduler,\n)\nwrite_reply = Task(\n    description=\"Write a reply to the patient's question '{question}' using only the schedule found earlier. Two sentences at most.\",\n    expected_output=\"A two-sentence reply for the patient.\",\n    agent=writer,\n    context=[find_doctors],    # this task receives the first task's output\n)\n\ncrew = Crew(agents=[scheduler, writer], tasks=[find_doctors, write_reply], process=Process.sequential, verbose=False)\n\nif __name__ == \"__main__\":\n    result = crew.kickoff(inputs={\"question\": \"Which cardiologist can I see on Thursday?\"})\n    print(result.raw)\n    print(\"\\nper task:\")\n    for t in result.tasks_output:\n        print(f\"  {t.agent}: {t.raw[:70]}\")\n    print(\"\\ntokens reported by CrewAI:\", result.token_usage.total_tokens)   # cross-check with your provider's usage page\n","ch24/clinic_tools.py":"\"\"\"The Chapter 9 clinic functions, wrapped as CrewAI tools.\n\nA CrewAI tool is a function plus a name and a docstring. The agent's model reads the docstring\nand the type hints to decide when to call it, exactly like the tool descriptions in Chapter 6.\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch09\"))\nimport clinic  # noqa: E402\nfrom crewai.tools import tool  # noqa: E402\n\n\n@tool(\"get_doctor_schedule\")\ndef get_doctor_schedule(department: str) -> str:\n    \"\"\"Look up which doctors in a hospital department see patients on which weekdays.\n    Input: a department name such as cardiology, orthopaedics or paediatrics.\"\"\"\n    return json.dumps(clinic.get_doctor_schedule(department))\n\n\n@tool(\"request_appointment\")\ndef request_appointment(doctor: str, day: str, patient_name: str) -> str:\n    \"\"\"Create an appointment REQUEST for staff to approve. It does not confirm a booking.\n    Only use it after the patient has asked to book and given their name.\"\"\"\n    return json.dumps(clinic.request_appointment(doctor, day, patient_name))\n","ch24/crew_llm.py":"\"\"\"One place that picks the model for every crew in this chapter.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nCrewAI names models \"<provider>/<model>\"; plain names default to OpenAI.\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nfrom crewai import LLM  # noqa: E402  (after load_dotenv so keys are visible)\n\n\ndef get_llm(temperature: float = 0, max_tokens: int = 700) -> LLM:\n    if os.getenv(\"PROVIDER\", \"openai\").lower() == \"anthropic\":\n        model = \"anthropic/\" + os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")\n    else:\n        model = os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\")\n    return LLM(model=model, temperature=temperature, max_tokens=max_tokens, timeout=30)\n","ch24/guarded_crew.py":"\"\"\"A crew you can trust in production: typed output, a guardrail that checks it, a human check, and limits.\n\n1. output_pydantic : the task must return this exact shape (like Chapter 6's structured output)\n2. guardrail       : plain Python that accepts or rejects the output; a rejection goes back to the agent to retry\n3. human_input     : the person reviews the result before the crew moves on\n4. limits          : max_iter, max_execution_time and max_retry_limit stop runaway agents\n\nRun:  python guarded_crew.py          (asks you to approve at the end; press Enter to accept)\n\"\"\"\nimport re\nfrom typing import Any, Literal, Tuple\n\nfrom crewai import Agent, Crew, Process, Task, TaskOutput\nfrom pydantic import BaseModel, Field\n\nfrom clinic_tools import get_doctor_schedule\nfrom crew_llm import get_llm\n\n\nclass PatientReply(BaseModel):\n    intent: Literal[\"schedule\", \"billing\", \"emergency\", \"other\"]\n    reply: str = Field(description=\"Message for the patient, two sentences at most\")\n    needs_human: bool = Field(description=\"True if staff must look at this before anything is sent\")\n\n\nMEDICAL = re.compile(r\"\\b(take|dose|dosage|mg|tablet|prescri\\w+|diagnos\\w+)\\b\", re.I)\n\n\ndef reply_guardrail(output: TaskOutput) -> Tuple[bool, Any]:   # CrewAI checks this exact annotation\n    \"\"\"Return (True, output) to accept, or (False, \"what is wrong\") to send the agent back to fix it.\"\"\"\n    data = output.pydantic\n    if data is None:\n        return False, \"Return the PatientReply JSON.\"\n    if MEDICAL.search(data.reply):\n        return False, \"The reply looks like medical advice. Remove it and point the patient to a doctor.\"\n    if data.intent == \"emergency\" and \"108\" not in data.reply:\n        return False, \"Emergencies must tell the patient to call 108.\"\n    if len(data.reply.split()) > 60:\n        return False, \"Too long. Two sentences at most.\"\n    return True, output\n\n\nagent = Agent(\n    role=\"Clinic helpdesk agent\",\n    goal=\"Answer the patient from the schedule tool and clinic rules; hand over anything you are unsure of\",\n    backstory=\"City Clinic helpdesk. No medical advice. Emergencies: tell the patient to call 108.\",\n    tools=[get_doctor_schedule],\n    llm=get_llm(),\n    max_iter=4,\n    max_execution_time=60,     # seconds; a hard stop even if the model keeps going\n    max_retry_limit=1,         # retries after an error\n    allow_delegation=False,\n)\n\nreply_task = Task(\n    description=\"Patient message: '{message}'. Classify it and write the reply.\",\n    expected_output=\"A PatientReply object.\",\n    agent=agent,\n    output_pydantic=PatientReply,\n    guardrail=reply_guardrail,\n    guardrail_max_retries=2,   # after two failed fixes the task fails loudly instead of looping\n    human_input=True,          # pauses for a person to approve or give feedback (set False for unattended runs)\n)\n\ncrew = Crew(agents=[agent], tasks=[reply_task], process=Process.sequential, verbose=False)\n\nif __name__ == \"__main__\":\n    out = crew.kickoff(inputs={\"message\": \"Which cardiologist is in on Thursday?\"})\n    print(out.pydantic.model_dump())\n","ch24/hierarchical_crew.py":"\"\"\"A hierarchical crew: a manager agent decides who does each task, like the supervisor in Chapter 23.\n\nYou give the crew tasks WITHOUT assigning agents. The manager reads them, delegates to the specialists,\nchecks the answers and combines them. That is flexible, and it costs extra model calls for the manager.\n\nRun:  python hierarchical_crew.py\n\"\"\"\nfrom crewai import Agent, Crew, Process, Task\n\nfrom clinic_tools import get_doctor_schedule\nfrom crew_llm import get_llm\n\nllm = get_llm()\nFACTS = (\"OPD registration fee Rs 100, valid 7 days for the same doctor. ECG Rs 350. Refunds need billing-desk approval. \"\n         \"PM-JAY, CGHS and the state scheme are accepted; planned admissions need pre-authorisation 48 hours ahead.\")\n\nscheduling = Agent(role=\"Scheduling desk\", goal=\"Answer doctor and day questions from the schedule tool\",\n                   backstory=\"City Clinic scheduling desk. Never guesses.\", tools=[get_doctor_schedule], llm=llm,\n                   allow_delegation=False, max_iter=4)\nbilling = Agent(role=\"Billing and insurance desk\", goal=\"Answer fee and insurance questions from the facts you hold\",\n                backstory=f\"City Clinic billing desk. Facts: {FACTS} Never gives medical advice.\", llm=llm,\n                allow_delegation=False)\n\ntask = Task(\n    description=\"A patient asks: '{question}'. Answer every part of the question.\",\n    expected_output=\"A short reply covering each part, in at most three sentences.\",\n    # no agent= here: the manager chooses\n)\n\ncrew = Crew(\n    agents=[scheduling, billing],\n    tasks=[task],\n    process=Process.hierarchical,\n    manager_llm=llm,           # or manager_agent=Agent(...) for a manager with its own role and rules\n    verbose=False,\n)\n\nif __name__ == \"__main__\":\n    print(crew.kickoff(inputs={\"question\": \"Is Dr Rao in on Thursday, and what is the OPD fee?\"}).raw)\n","ch24/mcp_crew.py":"\"\"\"Give a CrewAI agent the tools of an MCP server (Chapter 16's clinic server).\n\nMCPServerAdapter starts the server, lists its tools and wraps each one as a CrewAI tool.\nThe `with` block closes the server again, even when the crew fails.\n\nRun:  python mcp_crew.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nfrom crewai import Agent, Crew, Process, Task\nfrom crewai_tools import MCPServerAdapter\nfrom mcp import StdioServerParameters\n\nfrom crew_llm import get_llm\n\nSERVER = Path(__file__).resolve().parent.parent / \"ch16\" / \"clinic_server.py\"\nparams = StdioServerParameters(command=sys.executable, args=[str(SERVER)])\n\nif __name__ == \"__main__\":\n    # Passing tool names (\"get_doctor_schedule\") gives the agent ONLY those tools: least privilege, as in Chapter 17.\n    with MCPServerAdapter(params, \"get_doctor_schedule\", connect_timeout=30) as tools:\n        print(\"tools from the server:\", [t.name for t in tools])\n        desk = Agent(role=\"Scheduling desk\", goal=\"Answer schedule questions using the clinic's MCP tools\",\n                     backstory=\"City Clinic front desk. Never guesses.\", tools=list(tools), llm=get_llm(),\n                     max_iter=4, allow_delegation=False)\n        task = Task(description=\"{question}\", expected_output=\"One short sentence.\", agent=desk)\n        crew = Crew(agents=[desk], tasks=[task], process=Process.sequential)\n        print(crew.kickoff(inputs={\"question\": \"Which orthopaedics doctor sees patients on Tuesday?\"}).raw)\n","ch24/requirements-crewai.txt":"# CrewAI in its OWN virtual environment: crewai 1.15 depends on openai 2.x, while the rest of the course uses openai 3.x.\n#   python -m venv .venv-crew && source .venv-crew/bin/activate && pip install -r requirements-crewai.txt\ncrewai[anthropic]==1.15.35\ncrewai-tools[mcp]==1.15.35\npython-dotenv>=1.0\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
